// minimal fake of the Bedrock script API, just enough to exercise stage-1 logic
const mk = () => { const s = new Set(); return { subscribe: (f) => s.add(f), emit: (e) => s.forEach((f) => f(e)) }; };
export const events = {};
const ev = (n) => (events[n] ??= mk());
export const ItemStack = class { constructor(typeId, amount = 1) { this.typeId = typeId; this.amount = amount; } };
export const state = { tick: 0, abs: 0, players: [], pets: [], runQueue: [], intervals: [], messages: [] };
export const system = {
  get currentTick() { return state.tick; },
  run: (f) => state.runQueue.push(f),
  runInterval: (f) => state.intervals.push(f),
};
const dim = (id) => ({
  id,
  getEntities: () => state.pets.filter((p) => p.dimension.id === id),
  getPlayers: ({ location, maxDistance } = {}) => state.players.filter((p) => !maxDistance || Math.hypot(p.location.x - location.x, p.location.z - location.z) <= maxDistance),
  spawnItem: (i) => state.messages.push("drop " + i.typeId),
  getBlock: () => undefined,
});
export const dims = { overworld: dim("overworld"), nether: dim("nether"), the_end: dim("the_end") };
export const world = {
  afterEvents: new Proxy({}, { get: (_, n) => ev("after." + n) }),
  getAbsoluteTime: () => state.abs,
  getTimeOfDay: () => 1000,
  getDimension: (id) => dims[id],
  getAllPlayers: () => state.players,
  getDynamicProperty: () => undefined,
  setDynamicProperty: () => {},
};
export function makeContainer(size = 36) {
  const slots = Array(size).fill(undefined);
  return {
    size, slots,
    getItem: (i) => slots[i], setItem: (i, s) => { slots[i] = s; },
    addItem: (st) => { const i = slots.findIndex((x) => !x); if (i < 0) return st; slots[i] = st; return undefined; },
  };
}
export function makePlayer(id, x = 0, d = "overworld") {
  const container = makeContainer();
  const props = {};
  return {
    id, typeId: "minecraft:player", isSneaking: false, location: { x, y: 64, z: 0 }, dimension: dims[d], props,
    sendMessage: (m) => state.messages.push(`[${id}] ${m}`),
    getComponent: (c) => (c === "minecraft:inventory" ? { container } : undefined),
    getDynamicProperty: (k) => props[k], setDynamicProperty: (k, v) => { props[k] = v; }, container,
  };
}
export function makePet(typeId, x = 3, d = "overworld", tamed = true) {
  const container = makeContainer(16); const props = {};
  return {
    typeId, isValid: true, nameTag: "", location: { x, y: 64, z: 0 }, dimension: dims[d], props, events: [], effects: [], container,
    getComponent: (c) => (c === "minecraft:is_tamed" ? (tamed ? {} : undefined) : c === "minecraft:inventory" ? { container } : undefined),
    getDynamicProperty: (k) => props[k], setDynamicProperty: (k, v) => { if (v === undefined) delete props[k]; else props[k] = v; },
    teleport(loc, o) { this.location = { ...loc }; this.dimension = o.dimension; },
    triggerEvent(e) { this.events.push(e); }, addEffect(n, d2) { this.effects.push([n, d2]); },
  };
}
export const flush = () => { while (state.runQueue.length) state.runQueue.shift()(); };
export const emit = (n, e) => ev(n).emit(e);
